<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch, nextTick } from 'vue';
import { api, post, query, download, stateName, factoryName, prettyTime, token } from './api';
import AgentPanel from './AgentPanel.vue';
import ReportBoard from './ReportBoard.vue';
import ResultCard from './ResultCard.vue';
import EnergyChart from './EnergyChart.vue';

const boot = ref(null), loginBusy = ref(false), loginError = ref(''), loginUser = ref('admin'), loginPassword = ref('Demo@2026');
const view = ref('overview'), factory = ref('ALL'), notice = ref(''), error = ref(''), loading = ref(false);
const overviewAssets = ref(null), overviewPlans = ref(null);
const assetData = ref(null), planData = ref(null), snapshots = ref([]), imports = ref([]), approvals = ref([]), runs = ref([]);
const assetQuery = ref(''), assetState = ref(''), assetLine = ref(''), assetPage = ref(1), selected = ref([]);
const planStatus = ref(''), planType = ref(''), planQuery = ref('');
const reportPeriod = ref('2026-10'), reportTemplate = ref('V2'), reportFactories = ref(['F01', 'F02', 'F03']), currentRun = ref(null), reportBusy = ref(false);
const uploadFactory = ref('F03'), uploadPurpose = ref('snapshot'), uploadPeriod = ref('2026-10'), uploadFile = ref(null), uploadSynthetic = ref(false), uploadBusy = ref(false), batch = ref(null);
const energyFactory = ref('F02'), energyData = ref(null);
const source = ref(null), classifyOpen = ref(false), classifyValue = ref('工艺设备'), importance = ref('待评定'), reason = ref('');
const manualPlan = ref(null), manualState = ref('进行中'), manualNote = ref(''), manualResult = ref(''), manualCompleted = ref(''), confirmation = ref(null);
const approvalAsset = ref(''), approvalText = ref(''), approvalKey = ref(crypto.randomUUID());
const assistant = ref(null);
let timer, searchTimer, generation = 0;
const nav = [ ['overview','◈','协作总览','WORKSPACE'],['assistant','✦','业务助手',''],['assets','▦','资产台账','业务管理'],['imports','⇧','工厂上报',''],['plans','☷','检维修计划',''],['energy','⌁','能耗分析',''],['approvals','▱','审批示意',''],['settings','⚙','演示设置','系统'] ];
const titles = { overview: ['机动能源协作中心','把分散在各厂的工作，汇成一份清晰的进展。'], assistant: ['业务助手','交代任务，跟踪过程，核对结果。'], assets: ['资产台账','全部设备与工艺设备，共用一份真实档案。'], imports: ['工厂上报','从各厂文件开始，确认映射与月度盘点。'], plans: ['检维修计划','跟进零星维修、大修与巡检的实际进展。'], energy: ['能耗分析','在相同计量范围与期间下，查看模拟用电变化。'], approvals: ['审批示意','集中展示待处理事项，本版不流转审批。'], settings: ['演示设置','查看模型状态、演示数据与版本说明。'] };
const activeTitle = computed(() => titles[view.value]);
const isHQ = computed(() => boot.value?.user.role === 'HQ');
const canEditAssets = computed(() => boot.value?.user.role !== 'TECH');
const availableLines = computed(() => boot.value?.factories.find(f => f.id === factory.value)?.lines || []);
const currentSnapshots = computed(() => snapshots.value.filter(s => s.factory === uploadFactory.value && s.period === uploadPeriod.value));
const workCount = computed(() => overviewPlans.value?.uncompleted_count ?? 0);
const completedReports = computed(() => runs.value.filter(r => r.state === 'success').length);
const jsonText = value => JSON.stringify(value, null, 2);
const fieldLabel = key => ({ code:'设备编码', name:'资产名称', support:'支持状态', priority:'运行设备主次', line:'生产线', department:'使用部门', enabled_date:'启用日期', value:'原值（元）', condition:'完好状态', manufactured_month:'出厂年月', equipment_state:'设备状态', category:'资产类别', classification:'设备分类', source:'资产来源' }[key] || '未匹配');
function fail(message) { error.value = message; notice.value = ''; }
function toast(message) { notice.value = message; error.value = ''; setTimeout(() => { notice.value = ''; }, 4500); }
async function action(fn) { try { return await fn(); } catch (e) { fail(e.message); return null; } }
async function initialize() {
  assetData.value = null; planData.value = null; overviewAssets.value = null; overviewPlans.value = null; runs.value = []; snapshots.value = []; imports.value = []; approvals.value = []; source.value = null; currentRun.value = null;
  boot.value = await api('/bootstrap'); factory.value = boot.value.user.factory;
  uploadFactory.value = isHQ.value ? 'F03' : factory.value; energyFactory.value = isHQ.value ? 'F02' : factory.value;
  manualCompleted.value = boot.value.today;
  await refresh();
}
async function login() { loginBusy.value = true; loginError.value = ''; try { const r = await post('/login', { username: loginUser.value, password: loginPassword.value }); sessionStorage.setItem('wms-demo-token', r.token); await initialize(); } catch (e) { loginError.value = e.message; } finally { loginBusy.value = false; } }
function expired() { sessionStorage.removeItem('wms-demo-token'); boot.value = null; generation++; clearTimeout(timer); loginError.value = '会话已失效，请重新登录。'; }
async function logout() { await action(() => post('/logout')); sessionStorage.removeItem('wms-demo-token'); boot.value = null; generation++; clearTimeout(timer); currentRun.value = null; view.value = 'overview'; }
async function loadAssets() { const g = generation; const d = await api('/assets' + query({ factory_id: factory.value, query: assetQuery.value, equipment_state: assetState.value, line: assetLine.value, page: assetPage.value, page_size: 20 })); if (g === generation) assetData.value = d; }
async function loadPlans() { const g = generation; const d = await api('/plans' + query({ factory_id: factory.value, status: planStatus.value, type: planType.value, query: planQuery.value })); if (g === generation) planData.value = d; }
async function refresh() {
  if (!boot.value) return; const g = generation; loading.value = true;
  try { const [, , ss, im, ap, jobs, oa, op] = await Promise.all([loadAssets(), loadPlans(), api('/snapshots'), api('/imports'), api('/approvals'), api('/runs'), api('/assets' + query({ factory_id: factory.value, page_size: 1 })), api('/plans' + query({ factory_id: factory.value }))]); if (g !== generation) return; snapshots.value = ss; imports.value = im; approvals.value = ap; runs.value = jobs; overviewAssets.value = oa; overviewPlans.value = op; }
  catch (e) { fail(e.message); } finally { if (g === generation) loading.value = false; }
}
watch(factory, (value, old) => { if (!boot.value || value === old) return; generation++; clearTimeout(timer); currentRun.value = null; source.value = null; selected.value = []; assetPage.value = 1; assetLine.value = ''; assetQuery.value = ''; assetState.value = ''; if (value !== 'ALL') { uploadFactory.value = value; energyFactory.value = value; } energyData.value = null; refresh(); });
watch([assetQuery, assetState, assetLine], () => { selected.value = []; assetPage.value = 1; clearTimeout(searchTimer); searchTimer = setTimeout(() => action(loadAssets), 250); });
watch([planQuery, planStatus, planType], () => { clearTimeout(searchTimer); searchTimer = setTimeout(() => action(loadPlans), 250); });
watch(uploadFactory, () => { batch.value = null; });
async function ask(message) { view.value = 'assistant'; await nextTick(); assistant.value?.send(message); }
async function showSource(id) { const r = await action(() => api(`/sources/${encodeURIComponent(id)}`)); if (r) source.value = r; }
async function openReport(id) { view.value = 'overview'; clearTimeout(timer); const g = generation; const r = await action(() => api(`/runs/${id}`)); if (r && g === generation) { currentRun.value = r; if (['queued','running'].includes(r.state)) timer = setTimeout(() => pollReport(id, g), 900); } }
async function pollReport(id, g) { if (g !== generation || !boot.value) return; const r = await action(() => api(`/runs/${id}`)); if (!r || g !== generation) return; currentRun.value = r; if (['queued','running'].includes(r.state)) timer = setTimeout(() => pollReport(id, g), 900); else refresh(); }
async function startReport() { reportBusy.value = true; const r = await action(() => post('/reports', { factory_ids: reportFactories.value, period: reportPeriod.value, template: reportTemplate.value, request_key: crypto.randomUUID() })); if (r) openReport(r.id); reportBusy.value = false; }
async function runAction(kind) { if (!currentRun.value) return; const id = currentRun.value.id; const r = await action(() => post(`/runs/${id}/${kind}`)); if (r) openReport(id); }
async function preview() { if (!uploadFile.value) return fail('请先选择 Excel 或 CSV 文件'); uploadBusy.value = true; const form = new FormData(); form.append('file', uploadFile.value); form.append('factory', uploadFactory.value); form.append('purpose', uploadPurpose.value); form.append('period', uploadPeriod.value); form.append('synthetic', uploadSynthetic.value); const r = await action(() => api('/imports/preview', { method: 'POST', body: form })); if (r) batch.value = r; uploadBusy.value = false; refresh(); }
async function confirmImport() { uploadBusy.value = true; const r = await action(() => post(`/imports/${batch.value.id}/confirm`)); if (r) { batch.value = r; toast(`已确认 ${r.committed_count} 行，来源版本已保存。`); refresh(); } uploadBusy.value = false; }
async function voidImport(id) { const r = await action(() => post(`/imports/${id}/void`)); if (r) { toast(`已逻辑撤销 ${r.voided} 条新增档案`); refresh(); } }
async function openBatch(id) { const r = await action(() => api(`/imports/${id}`)); if (r) batch.value = r; }
async function classify() { const list = assetData.value.records.filter(r => selected.value.includes(r.id)).map(r => ({ id: r.id, version: r.version })); const r = await action(() => post('/assets/classify', { assets: list, classification: classifyValue.value, importance: importance.value, reason: reason.value })); if (r) { classifyOpen.value = false; selected.value = []; reason.value = ''; toast(`已更新 ${r.updated} 条设备分类`); refresh(); } }
async function paginate(delta) { assetPage.value += delta; selected.value = []; await action(loadAssets); }
async function loadEnergy() { const r = await action(() => api('/energy' + query(energyParams()))); if (r) energyData.value = r; }
function energyParams() { return { factory_id: energyFactory.value, start: '2026-11-01', end: '2026-11-16', compare_start: '2026-10-01', compare_end: '2026-10-16' }; }
function editPlan(p) { manualPlan.value = p; manualState.value = ['待执行','受阻'].includes(p.state) ? '进行中' : p.state; manualNote.value = p.note || ''; manualResult.value = p.result || ''; }
async function proposeManual() { const r = await action(() => post('/plans/propose', { action: 'update', task_id: manualPlan.value.id, state: manualState.value, note: manualNote.value, ...(manualState.value === '已完成' ? { result: manualResult.value, completed_at: manualCompleted.value } : {}) })); if (r) { manualPlan.value = null; confirmation.value = r; } }
async function submitApproval() { const r = await action(() => post('/approvals', { asset_id: approvalAsset.value, description: approvalText.value, request_key: approvalKey.value })); if (r) { approvalKey.value = crypto.randomUUID(); approvalText.value = ''; toast('事项已进入审批示意页，资产数据未改变'); refresh(); } }
const fixtures = [['a','一厂 · 标准中文'],['b','二厂 · 英文别名'],['bad','三厂 · 缺字段样例'],['c','三厂 · 修正文件'],['template','Excel 空模板']];
const fileNames = { a:'F01_A_2026-10_模拟盘点.csv', b:'F02_B_2026-10_模拟盘点.csv', c:'F03_C_2026-10_模拟盘点.csv', bad:'F03_C_缺少运行状态_错误样例.csv', template:'设备导入模板.xlsx' };
onMounted(async () => { window.addEventListener('demo-session-expired', expired); if (token()) await action(initialize); });
onBeforeUnmount(() => { generation++; clearTimeout(timer); clearTimeout(searchTimer); window.removeEventListener('demo-session-expired', expired); });
</script>

<template>
  <div v-if="!boot" class="login-screen"><section class="login-story"><div class="brand"><span class="brand-mark">W</span><strong>WMS <span>Agent</span></strong></div><span class="eyebrow">工业资产 · 检维修协作</span><h1>让每个工厂的进展，<br>都有清晰的回应。</h1><p>从一张设备表，到一次跨厂协作。<br>让业务助手帮你查数据、跟计划、汇月报。</p><div class="login-network"><span>01 厂</span><i>↘</i><strong>✦ Main Agent</strong><i>↗</i><span>02 厂</span><span>03 厂</span></div><small>DEMO V1.0.0 · 全部使用合成演示数据</small></section><section class="login-card"><span class="tag green">功能演示环境</span><h2>进入协作工作台</h2><p class="muted">选择演示身份，体验不同的工厂权限。</p><div class="account-picker"><button :class="{ active: loginUser === 'admin' }" @click="loginUser = 'admin'">总部</button><button :class="{ active: loginUser === 'factory01' }" @click="loginUser = 'factory01'">一厂资产员</button><button :class="{ active: loginUser === 'tech02' }" @click="loginUser = 'tech02'">二厂维修员</button></div><form @submit.prevent="login"><label>演示账号<input v-model="loginUser" autocomplete="username" /></label><label>登录密码<input v-model="loginPassword" type="password" autocomplete="current-password" /></label><p v-if="loginError" class="inline-error">{{ loginError }}</p><button class="primary wide" :disabled="loginBusy">{{ loginBusy ? '正在登录…' : '进入工作台 →' }}</button></form><p class="muted small">演示密码：Demo@2026<br>服务端验证身份；工厂账号仅能访问本厂数据。</p></section></div>
  <div v-else class="demo-shell">
    <aside class="sidebar"><div class="brand"><span class="brand-mark">W</span><strong>WMS <span>Agent</span></strong></div><div class="workspace-label"><span class="mini-dot" />机动能源部 · 演示空间</div><nav><template v-for="[id,icon,label,group] in nav" :key="id"><small v-if="group" class="nav-group">{{ group }}</small><button :class="{ active: view === id }" @click="view = id; error = ''"><span class="nav-icon">{{ icon }}</span>{{ label }}<span v-if="id === 'assistant'" class="ai-label">AI</span></button></template></nav><div class="sidebar-bottom"><div class="model-indicator"><span class="online-dot" :class="{ offline: !boot.model.configured }" /><div><strong>DeepSeek</strong><small>{{ boot.model.configured ? '官方 API · 已配置' : '等待配置凭据' }}</small></div></div><span class="version-note">Demo V1.0.0 · PRD V4.1</span></div></aside>
    <div class="content-shell"><header class="topbar"><div class="breadcrumb">工业资产协作 <span>/</span> {{ activeTitle[0] }}</div><div class="topbar-actions"><span class="tag amber">合成演示数据</span><label class="scope-picker"><span>当前范围</span><select v-model="factory" aria-label="当前工厂范围"><option v-if="isHQ" value="ALL">全部 12 厂</option><option v-for="f in boot.factories" :key="f.id" :value="f.id">{{ factoryName(f.id) }}</option></select></label><button class="user-button" @click="logout" title="退出登录"><span>{{ boot.user.name.slice(0,1) }}</span><div>{{ boot.user.name }}<small>退出登录</small></div></button></div></header>
      <main class="page"><div class="page-heading"><div><h1>{{ activeTitle[0] }}</h1><p>{{ activeTitle[1] }}</p></div><button class="secondary" :disabled="loading" @click="refresh">↻ {{ loading ? '刷新中' : '刷新数据' }}</button></div><div v-if="error" class="notice error" role="alert">{{ error }}<button @click="error = ''">×</button></div><div v-if="notice" class="notice" role="status">{{ notice }}</div>
      <template v-if="view === 'overview'"><div class="overview-metrics metric-grid"><article><span>当前范围 · 全部设备</span><strong>{{ overviewAssets?.total ?? '—' }}<small> 台</small></strong><p>工艺 {{ overviewAssets?.process_count ?? '—' }} · 非工艺 {{ overviewAssets?.nonprocess_count ?? '—' }}</p></article><article><span>工厂协作范围</span><strong>{{ isHQ ? '12' : '1' }}<small> 个厂</small></strong><p>首版月报启用 01 / 02 / 03 厂</p></article><article><span>当前范围 · 未完成计划</span><strong>{{ workCount }}<small> 项</small></strong><p>零星维修 · 大修 · 巡检</p></article><article><span>已完成月报任务</span><strong>{{ completedReports }}<small> 份</small></strong><p>按真实运行状态统计</p></article></div>
        <div class="overview-layout"><div class="workspace-main"><section v-if="!currentRun" class="hero-panel"><span class="eyebrow">从分散记录，到协作结果</span><h2>给总部一个目标，<br>让各厂 Agent 一起办理。</h2><p>不同格式的盘点表，统一的汇报口径。<br>处理过程、缺项和结果来源，都在这里。</p><div class="hero-orbit"><span>01</span><span>02</span><span>03</span><i>✦</i></div><div class="hero-footer"><span>主 Agent 协调</span><b>→</b><span>工厂独立处理</span><b>→</b><span>统一月报</span></div></section>
          <section v-if="isHQ" class="panel report-form"><div class="section-heading"><h3>交办一份月报</h3><span class="tag">人工发起 · 真实 Agent 执行</span></div><div class="form-row"><label>统计月份<input type="month" v-model="reportPeriod" /></label><label>汇报模板<select v-model="reportTemplate"><option value="V1">V1 · 资产与计划</option><option value="V2">V2 · 增加停机设备</option></select></label></div><div class="report-scope"><label v-for="f in ['F01','F02','F03']" :key="f"><input type="checkbox" v-model="reportFactories" :value="f" />{{ factoryName(f) }}</label><span>本次 {{ reportFactories.length }}/12 厂</span></div><button class="primary" :disabled="reportBusy || !reportFactories.length" @click="startReport">✦ {{ reportBusy ? '正在交办…' : '让 Agent 归集月报' }}</button><p class="muted small">初始数据中一、二厂已确认 10 月盘点，三厂等待上报；补齐后可单独重试。</p></section>
          <ReportBoard v-if="currentRun" :run="currentRun" @retry="runAction('retry')" @cancel="runAction('cancel')" @confirm="runAction('confirm')" @export="action(() => download(`/runs/${currentRun.id}/export`, `WMS_${currentRun.period}_模拟月报.csv`))" @source="showSource" />
          <section v-if="runs.length" class="panel"><div class="section-heading"><h3>最近的月报任务</h3><span class="muted small">可追溯版本</span></div><button v-for="r in runs.slice(0,8)" :key="r.id" class="job-row" @click="openReport(r.id)"><span class="file-icon">▤</span><div><strong>{{ r.period }} · {{ r.template }} 月报</strong><small>{{ prettyTime(r.created_at) }} · {{ r.factory_ids?.map(factoryName).join(' / ') }}</small></div><span class="tag" :class="r.state === 'success' ? 'green' : ''">{{ stateName(r.state) }}</span><b>↗</b></button></section>
        </div><AgentPanel :factory="factory" :model="boot.model" @source="showSource" @report="openReport" @changed="refresh" @error="fail" /></div>
      </template>
      <AgentPanel v-else-if="view === 'assistant'" ref="assistant" full :factory="factory" :model="boot.model" @source="showSource" @report="openReport" @changed="refresh" @error="fail" />
      <template v-else-if="view === 'assets'"><section class="panel"><div class="filter-bar"><input v-model="assetQuery" placeholder="搜索设备名称 / 编码" aria-label="搜索设备" /><select v-model="assetState" aria-label="设备状态"><option value="">全部状态</option><option>在用</option><option>已停机</option><option>待确认</option></select><select v-model="assetLine" aria-label="生产线"><option value="">全部生产线</option><option v-for="l in availableLines" :key="l">{{ l }}</option></select><button v-if="canEditAssets" class="secondary" :disabled="!selected.length" @click="classifyOpen = true">批量分类（{{ selected.length }}）</button><button class="primary" @click="ask(`查询${factory === 'ALL' ? '所有授权工厂' : factoryName(factory)}的空调资产状态`)">✦ 让助手查询</button></div><div class="asset-counts"><span>全部 <b>{{ assetData?.total }}</b></span><span>工艺 <b>{{ assetData?.process_count }}</b></span><span>非工艺 <b>{{ assetData?.nonprocess_count }}</b></span><span>待分类 <b>{{ assetData?.unclassified_count }}</b></span></div></section><div class="dual-tables"><section v-for="side in ['all','process']" :key="side" class="panel"><div class="section-heading"><h3>{{ side === 'all' ? '全部设备' : '工艺设备' }}</h3><span class="tag" :class="side === 'process' ? 'green' : ''">{{ side === 'all' ? '含非生产设备' : '生产相关子集' }}</span></div><div class="table-wrap asset-scroll"><table><thead><tr><th v-if="side === 'all'">选择</th><th>设备 / 编码</th><th>工厂</th><th>状态</th><th>重要度</th></tr></thead><tbody><tr v-for="r in (side === 'all' ? assetData?.records : assetData?.process_records)" :key="r.id"><td v-if="side === 'all'"><input type="checkbox" v-model="selected" :value="r.id" :aria-label="`选择${r.code}`" /></td><td><button class="text-button" @click="showSource(r.id)">{{ r.name }}</button><small class="cell-sub">{{ r.code }} · {{ r.classification }}</small></td><td>{{ factoryName(r.factory) }}</td><td><span class="tag" :class="r.equipment_state === '已停机' ? 'amber' : 'green'">{{ r.equipment_state }}</span></td><td>{{ r.importance || '待评定' }}</td></tr></tbody></table><p v-if="!(side === 'all' ? assetData?.records : assetData?.process_records)?.length" class="empty-state">当前条件下没有设备</p></div></section></div><div class="pagination"><span>第 {{ assetPage }} 页 · 每侧最多 20 条</span><button class="secondary" :disabled="assetPage <= 1" @click="paginate(-1)">上一页</button><button class="secondary" :disabled="!assetData?.has_more" @click="paginate(1)">下一页</button></div></template>
      <template v-else-if="view === 'imports'"><div class="import-layout"><section class="panel"><div class="section-heading"><h3>上传并预检</h3><span class="tag">Excel / CSV</span></div><div class="form-row"><label>上报工厂<select v-model="uploadFactory"><option v-for="f in boot.factories" :key="f.id" :value="f.id">{{ factoryName(f.id) }}</option></select></label><label>数据用途<select v-model="uploadPurpose"><option value="snapshot">月度盘点快照</option><option value="assets">新增资产档案</option></select></label></div><label v-if="uploadPurpose === 'snapshot'">统计月份<input type="month" v-model="uploadPeriod" /></label><label class="file-drop"><span>⇧</span><strong>选择一个 Excel 或 CSV 文件</strong><small>最多 5 MiB / 1000 行 · 标准 14 字段</small><input type="file" accept=".csv,.xlsx" @change="uploadFile = $event.target.files[0]" /></label><label class="checkbox-label"><input v-model="uploadSynthetic" type="checkbox" />我确认这是合成演示数据</label><button class="primary wide" :disabled="uploadBusy || !uploadSynthetic || !uploadFile || !canEditAssets" @click="preview">{{ uploadBusy ? '正在预检…' : '检查字段与数据' }}</button><p class="small muted">月度快照关联已有设备，保存历史状态；不会重复建立资产档案。</p></section><section class="panel"><span class="eyebrow">DEMO FILES</span><h3>从准备好的样例开始</h3><p class="muted">三个工厂采用不同布局；三厂提供错误与修正两个文件，可演示补齐流程。</p><button v-for="[key,label] in fixtures" :key="key" class="download-row" @click="action(() => download(`/fixtures/${key}`, fileNames[key]))"><span>▤ {{ label }}</span><b>↓</b></button><div class="subtle-box"><strong>{{ factoryName(uploadFactory) }} · {{ uploadPeriod }}</strong><p>{{ currentSnapshots.length ? `已有 ${currentSnapshots.length} 份确认快照。新提交将产生新版本。` : '暂无已确认快照，月报会显示该厂待补充。' }}</p></div></section></div>
        <section v-if="batch" class="panel"><div class="section-heading"><div><h3>{{ batch.filename }}</h3><p class="muted small">{{ batch.id }} · {{ factoryName(batch.factory) }} · {{ batch.row_count }} 行</p></div><span class="tag" :class="batch.state === 'invalid' ? 'amber' : 'green'">{{ stateName(batch.state) }}</span></div><div class="mapping-grid"><span v-for="(h,i) in batch.headers" :key="i">{{ h }}<b>→</b>{{ fieldLabel(batch.mapping[i]) }}</span></div><ul v-if="batch.errors?.length" class="issue-list"><li v-for="(e,i) in batch.errors.slice(0,20)" :key="i">第 {{ e.row }} 行：{{ e.message }}</li></ul><p v-for="(w,i) in batch.warnings?.slice(0,10)" :key="i" class="muted small">提示：第 {{ w.row }} 行，{{ w.message }}</p><div class="button-row"><button v-if="batch.state === 'preview'" class="primary" :disabled="uploadBusy" @click="confirmImport">确认映射并提交 {{ batch.row_count }} 行</button><button class="secondary" @click="ask(`检查上传批次 ${batch.id} 的映射和错误，告诉我需要补充什么`)">✦ 请助手检查</button><button class="text-button" @click="action(() => download(`/imports/${batch.id}/file`, batch.filename))">下载原文件</button></div></section>
        <section class="panel"><div class="section-heading"><h3>上报记录</h3><span class="muted small">原文件与确认版本均保留</span></div><div v-if="!imports.length" class="empty-state">上传第一份文件，开始本期盘点。</div><div v-for="b in imports.slice(0,12)" :key="b.id" class="job-row"><span class="file-icon">▤</span><button class="text-button grow" @click="openBatch(b.id)">{{ b.filename }}<small class="cell-sub">{{ factoryName(b.factory) }} · {{ b.purpose === 'snapshot' ? b.period + ' 月度快照' : '新增档案' }}</small></button><span class="tag">{{ stateName(b.state) }}</span><button v-if="isHQ && b.state === 'confirmed' && b.purpose === 'assets'" class="text-button danger-text" @click="voidImport(b.id)">逻辑撤销</button></div></section>
      </template>
      <template v-else-if="view === 'plans'"><section class="panel"><div class="filter-bar"><input v-model="planQuery" placeholder="搜索计划、设备、编号" aria-label="搜索计划" /><select v-model="planStatus" aria-label="计划状态"><option value="">全部状态</option><option>未完成</option><option>逾期</option><option>待执行</option><option>进行中</option><option>受阻</option><option>已完成</option><option>已取消</option></select><select v-model="planType" aria-label="作业类型"><option value="">全部类型</option><option>零星维修</option><option>大修</option><option>巡检</option></select><button class="primary" @click="ask(`请帮我为${factory === 'ALL' ? '二厂' : factoryName(factory)}的一台空调新建零星维修计划，先查询可选设备`)">✦ 对话创建计划</button></div><div class="table-wrap"><table><thead><tr><th>计划 / 编号</th><th>工厂</th><th>设备</th><th>类型</th><th>截止日期</th><th>进度</th><th>操作</th></tr></thead><tbody><tr v-for="p in planData?.records" :key="p.id"><td><strong>{{ p.title }}</strong><small class="cell-sub">{{ p.id }}</small></td><td>{{ factoryName(p.factory) }}</td><td>{{ p.asset_name }}</td><td>{{ p.type }}</td><td>{{ p.deadline }}</td><td><span class="tag" :class="p.state === '已完成' ? 'green' : p.state === '受阻' ? 'amber' : ''">{{ p.state }}</span></td><td><button class="text-button" @click="ask(`查询计划 ${p.id} 的当前状态`)">问助手</button><button v-if="!['已完成','已取消'].includes(p.state)" class="text-button" @click="editPlan(p)">更新</button><button class="text-button" @click="showSource(p.id)">详情</button></td></tr></tbody></table><p v-if="!planData?.records.length" class="empty-state">当前筛选下没有作业计划</p></div><p class="muted small">当前展示 {{ planData?.records.length }} / {{ planData?.total }} 条{{ planData?.has_more ? '，请缩小范围查看后续计划' : '' }}。完成任务需填写实际日期与结果。</p></section></template>
      <template v-else-if="view === 'energy'"><section class="panel"><div class="section-heading"><div><h3>空调用电 · 同期对比</h3><p class="muted">2026 年 11 月 1—16 日，对比 10 月 1—16 日。</p></div><span class="tag amber">模拟数据</span></div><div class="filter-bar"><select v-model="energyFactory" aria-label="能耗工厂" @change="energyData = null"><option v-for="f in boot.factories" :key="f.id" :value="f.id">{{ factoryName(f.id) }}</option></select><button class="secondary" @click="loadEnergy">查看模拟数据</button><button class="primary" @click="ask(`分析${factoryName(energyFactory)}空调2026年11月1日至16日模拟能耗，与2026年10月1日至16日对比`)">✦ 让助手分析</button><button v-if="energyData" class="text-button" @click="action(() => download('/energy/export' + query(energyParams()), '空调模拟能耗.csv'))">导出 CSV ↗</button></div><EnergyChart v-if="energyData" :data="energyData" @source="showSource" /><div v-else class="empty-state energy-placeholder">⌁<h3>选择工厂，查看一段用电变化</h3><p>同一计量点、相同长度期间，所有图表标明模拟来源。</p></div></section></template>
      <template v-else-if="view === 'approvals'"><section class="panel"><div class="section-heading"><h3>提交一个待处理事项</h3><span class="tag">仅作流程示意</span></div><div class="form-row"><label>设备稳定 ID<input v-model="approvalAsset" placeholder="例如 AS-F02-0025" /></label><label class="grow">事项说明<input v-model="approvalText" maxlength="500" placeholder="例如：申请核对设备用途分类" /></label><button class="primary" :disabled="!approvalAsset || !approvalText" @click="submitApproval">提交示意事项</button></div><p class="muted small">此处不审批、不改变资产分类；与计划保存前的确认卡分开。</p></section><section class="panel"><h3>待处理列表</h3><div v-if="!approvals.length" class="empty-state">暂无待处理事项</div><div v-for="r in approvals" :key="r.id" class="job-row"><div class="grow"><strong>{{ r.asset_name }}</strong><p>{{ r.description }}</p><small class="muted">{{ factoryName(r.factory) }} · {{ r.applicant }} · {{ prettyTime(r.created_at) }}</small></div><span class="tag amber">待处理</span></div></section></template>
      <template v-else-if="view === 'settings'"><div class="settings-grid"><section class="panel"><span class="eyebrow">MODEL CONNECTION</span><h3>DeepSeek 官方 API</h3><dl class="confirmation-fields"><dt>模型</dt><dd>{{ boot.model.model }}</dd><dt>凭据状态</dt><dd>{{ boot.model.configured ? '后端已读取本机配置' : '尚未配置' }}</dd><dt>业务数据</dt><dd>仅合成演示数据</dd><dt>运行方式</dt><dd>本地业务服务 + 官方模型 API</dd></dl><p class="muted small">模型凭据仅在服务端读取，前端不持有密钥。配置变化后刷新页面即可。执行是否成功，以任务轨迹为准。</p><button class="secondary" @click="action(async () => { boot.model = (await api('/bootstrap')).model; toast('模型配置状态已刷新'); })">刷新配置状态</button></section><section class="panel"><span class="eyebrow">DEMO BASELINE</span><h3>版本与演示范围</h3><p>Demo V1.0.0 · PRD V4.1</p><ul class="plain-list"><li>12 厂组织，432 台合成设备。</li><li>主 Agent 协调一、二、三厂月报。</li><li>V1 / V2 模板、失败厂补报重试。</li><li>对话查询、确认后修改计划。</li><li>模拟能耗、基础双表、审批示意。</li></ul><p class="muted small">文档与后续版本统一维护在 project/files。当前演示不自动对外发送报告。</p></section></div></template>
      </main><footer class="page-footer"><span>WMS Agent · 工业资产与检维修协作</span><span>合成演示环境 / V1.0.0</span></footer>
    </div>
    <div v-if="source" class="modal-backdrop" @click.self="source = null"><section class="source-drawer"><header><div><span class="eyebrow">SOURCE & EVIDENCE</span><h2>{{ source.name || source.title || source.filename || '业务来源' }}</h2><p class="muted small">{{ source.id }} · {{ factoryName(source.factory) }} · 版本 {{ source.version }}</p></div><button class="close-button" @click="source = null" aria-label="关闭来源">×</button></header><div class="drawer-content"><span class="tag amber">合成演示数据</span><dl v-if="source.kind === 'asset'" class="confirmation-fields"><template v-for="[key,label] in [['code','设备编码'],['name','资产名称'],['classification','设备分类'],['importance','重要度'],['equipment_state','设备状态'],['line','生产线'],['department','使用部门'],['enabled_date','启用日期'],['value','原值（元）'],['condition','完好状态'],['manufactured_month','出厂年月'],['priority','运行主次'],['support','支持状态'],['category','资产类别'],['source','资产来源']]" :key="key"><dt>{{ label }}</dt><dd>{{ source[key] || '未采集' }}</dd></template></dl><template v-else-if="source.kind === 'plan'"><dl class="confirmation-fields"><dt>设备</dt><dd>{{ source.asset_name }}</dd><dt>类型 / 状态</dt><dd>{{ source.type }} · {{ source.state }}</dd><dt>责任人</dt><dd>{{ source.assignee }}</dd><dt>计划截止</dt><dd>{{ source.deadline }}</dd><dt>进度备注</dt><dd>{{ source.note }}</dd><dt>完成结果</dt><dd>{{ source.result || '尚未记录' }}</dd><dt>完成日期</dt><dd>{{ source.completed_at || '尚未完成' }}</dd></dl><button class="primary" @click="ask(`查询计划 ${source.id}，并帮我跟进进度`); source = null">✦ 继续和助手办理</button></template><template v-else-if="source.rows"><p>{{ source.period || '数据导入' }} · {{ source.rows.length }} 条记录 · 来源 {{ source.source_ref || source.filename }}</p><div class="table-wrap"><table><thead><tr><th>设备编码</th><th>名称</th><th>状态</th><th>分类</th></tr></thead><tbody><tr v-for="(r,i) in source.rows.slice(0,100)" :key="i"><td>{{ r.code }}</td><td>{{ r.name }}</td><td>{{ r.equipment_state }}</td><td>{{ r.classification }}</td></tr></tbody></table></div><p v-if="source.rows.length > 100" class="muted">预览前 100 条，请下载原文件查看全量。</p><button v-if="source.kind === 'import'" class="secondary" @click="action(() => download(`/imports/${source.id}/file`, source.filename))">下载原文件</button></template><pre v-else class="source-json">{{ jsonText(source) }}</pre><p class="muted small">来源记录可核对；历史快照与当前资产档案可能不同。</p></div></section></div>
    <div v-if="classifyOpen" class="modal-backdrop" @click.self="classifyOpen = false"><section class="dialog"><header><h2>批量维护 {{ selected.length }} 条设备</h2><button class="close-button" @click="classifyOpen = false">×</button></header><label>设备用途<select v-model="classifyValue"><option>工艺设备</option><option>非工艺设备</option><option>待分类</option></select></label><label>重要度<select v-model="importance"><option>关键</option><option>重要</option><option>一般</option><option>待评定</option></select></label><label>调整原因<textarea v-model="reason" maxlength="500" placeholder="说明用途依据；关键设备请说明影响" /></label><button class="primary wide" :disabled="!reason.trim()" @click="classify">确认分类变更</button></section></div>
    <div v-if="manualPlan" class="modal-backdrop" @click.self="manualPlan = null"><section class="dialog"><header><div><h2>更新计划进度</h2><p class="muted small">{{ manualPlan.id }} · {{ manualPlan.title }}</p></div><button class="close-button" @click="manualPlan = null">×</button></header><label>目标状态<select v-model="manualState"><option>进行中</option><option>受阻</option><option>已完成</option></select></label><label>进度备注<textarea v-model="manualNote" maxlength="1000" /></label><template v-if="manualState === '已完成'"><label>完成日期<input type="date" v-model="manualCompleted" /></label><label>实际完成结果<textarea v-model="manualResult" placeholder="巡检须以正常、异常或待确认开头" /></label></template><button class="primary wide" @click="proposeManual">预览变更，下一步确认</button></section></div>
    <div v-if="confirmation" class="modal-backdrop" @click.self="confirmation = null"><section class="dialog"><header><h2>业务确认</h2><button class="close-button" @click="confirmation = null">×</button></header><ResultCard :card="confirmation" @changed="refresh" @error="fail" /></section></div>
  </div>
</template>
